const PERMS=['quotes','bookings','payments','tickets','inbox','pricing','content','customers','staff','loyalty','newsletter','analytics','settings','legal','chat'];
let sb=null,currentSession=null,currentProfile=null,currentPermissions={},runtimeConfig={},pricingCache=[],customerCache=[],staffAdminCache=[],bookingStaffCache=[],quoteCache=[],bookingCache=[],bookingChangeCache=[],paymentCache=[],feedbackCache=[],reportCache=null,customerActivityCache={quotes:[],bookings:[],projects:[]},bookingCalendarView='week',bookingCalendarDate=new Date(),areaMap=null,areaLayers=[],areaCache=[],editingAreaId=null,areaDraftMarker=null,areaDraftCircle=null,areaDraftPolygon=null,areaBoundaryVertexLayers=[],areaBoundaryPoints=[],areaDrawingBoundary=false,areaAdminCatalog=[],areaAdminSelected=new Map(),areaAdminGeojson=null,areaAdminBoundaryLayer=null,areaAdminBrowseLayer=null,areaAdminLoadTimer=null,areaAdminBrowseKey='',lastSavedAreaId=null,addressDirectoryCache={},staffNotificationCache=[],staffNotificationInboxCache=[],staffNotificationView='inbox',staffNotificationFilter='all',supportInboxCache=[],supportInboxStaff=[],supportInboxOpenId=null,supportInboxDrafts=new Map(),supportInboxLastUpdated=null,supportInboxRefreshing=false,managementPoll=null;
const esc=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const gbp=v=>Number(v||0).toLocaleString('en-GB',{minimumFractionDigits:0,maximumFractionDigits:2});
