function localDateValue(v){if(!v)return'';const d=new Date(v),pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`}
function localTimeValue(v){if(!v)return'';const d=new Date(v),pad=n=>String(n).padStart(2,'0');return `${pad(d.getHours())}:${pad(d.getMinutes())}`}
function crmEmpty(message){return `<div class="crm-empty">${esc(message)}</div>`}

function setBusy(btn,on,label='Please wait…'){if(on){btn.dataset.label=btn.textContent;btn.textContent=label;btn.disabled=true}else{btn.textContent=btn.dataset.label||btn.textContent;btn.disabled=false}}
async function api(path,options={},retryAuth=true){const headers={'Content-Type':'application/json',...(options.headers||{})};if(currentSession?.access_token)headers.Authorization=`Bearer ${currentSession.access_token}`;const r=await fetch(path,{...options,headers});if(r.status===401&&retryAuth&&sb?.auth){const {data,error}=await sb.auth.refreshSession();if(!error&&data?.session){currentSession=data.session;return api(path,options,false)}}const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||`Request failed (${r.status})`);return d}
function allowed(key){return currentProfile?.role==='admin'||currentPermissions[key]===true}
function applyPermissionTabs(){const map={reports:'analytics',quotes:'quotes',bookings:'bookings',payments:'payments',followups:'analytics',feedback:'tickets',tickets:'tickets',pricing:'pricing',content:'content',customers:'customers',staff:'staff',loyalty:'loyalty',newsletter:'newsletter',areas:'settings',website:'settings',chat:'chat'};for(const [tab,perm] of Object.entries(map)){const b=document.querySelector(`[data-tab="${tab}"]`);if(b)b.classList.toggle('hidden',!allowed(perm))}const inbox=document.querySelector('[data-tab="inbox"]');if(inbox)inbox.classList.toggle('hidden',!(allowed('inbox')||allowed('tickets')||allowed('bookings')||allowed('payments')));const activity=document.querySelector('[data-tab="activity"]');if(activity)activity.classList.toggle('hidden',currentProfile?.role!=='admin')}
function loadScriptOnce(src){return new Promise((resolve,reject)=>{const existing=[...document.scripts].find(x=>x.src===src);if(existing?.dataset.loaded==='true'){resolve();return}const script=existing||document.createElement('script');const done=()=>{script.dataset.loaded='true';resolve()};script.addEventListener('load',done,{once:true});script.addEventListener('error',()=>reject(new Error('The secure sign-in library could not be loaded. Check your connection and refresh.')),{once:true});if(!existing){script.src=src;script.async=true;document.head.appendChild(script)}})}
async function ensureSupabaseLibrary(){if(window.supabase?.createClient)return;await loadScriptOnce('https://unpkg.com/@supabase/supabase-js@2');if(!window.supabase?.createClient)throw new Error('The secure sign-in library is unavailable. Refresh the page and try again.')}
async function init(){const r=await fetch('/api/config',{cache:'no-store'}),c=await r.json();if(!r.ok||!c.ok)throw new Error(c.error||'Could not load configuration');if(!c.supabaseUrl||!c.supabaseAnonKey)throw new Error('Secure sign-in configuration is incomplete.');runtimeConfig=c;await ensureSupabaseLibrary();sb=window.supabase.createClient(c.supabaseUrl,c.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});if(!sb?.auth)throw new Error('Secure sign-in could not be initialised. Refresh the page and try again.');const {data:{session}}=await sb.auth.getSession();if(session)await enter(session);else showLogin();sb.auth.onAuthStateChange(async(_e,s)=>{if(s){const hadSession=!!currentSession;currentSession=s;if(!hadSession)await enter(s)}else showLogin()});$$('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close())}
function showLogin(msg=''){currentSession=null;currentProfile=null;currentPermissions={};$('#adminSessionLoading')?.classList.add('hidden');$('#adminApp').classList.add('hidden');$('#adminLogin').classList.remove('hidden');$('#adminLoginStatus').textContent=msg}
async function enter(session){currentSession=session;$('#adminSessionLoading')?.classList.add('hidden');const {data,error}=await sb.from('profiles').select('*').eq('id',session.user.id).single();if(error||!data||!['admin','staff'].includes(data.role)){await sb.auth.signOut();showLogin('This account does not have Namdar staff access.');return}currentProfile=data;if(data.role==='staff'){const {data:a}=await sb.from('staff_access').select('permissions,active,job_title').eq('user_id',data.id).maybeSingle();currentPermissions=a?.active?a.permissions||{}:{};$('#staffRoleLine').textContent=a?.job_title||'Namdar staff'}else{currentPermissions=Object.fromEntries(PERMS.map(x=>[x,true]));$('#staffRoleLine').textContent='Administrator'}applyPermissionTabs();$('#adminLogin').classList.add('hidden');$('#adminApp').classList.remove('hidden');await refreshAll();await openDeepLinkedAdminTab();startManagementPolling()}
async function counts(){const safe=async(q)=>{try{const r=await q;return r.count??0}catch{return 0}};$('#statViews').textContent=allowed('analytics')?await safe(sb.from('page_views').select('*',{count:'exact',head:true})): '—';$('#statQuotes').textContent=allowed('quotes')?await safe(sb.from('quotes').select('*',{count:'exact',head:true})):'—';$('#statBookings').textContent=allowed('bookings')?await safe(sb.from('bookings').select('*',{count:'exact',head:true})):'—';$('#statTickets').textContent=allowed('tickets')?await safe(sb.from('support_tickets').select('*',{count:'exact',head:true}).not('status','in','(closed,cancelled)').or('source.is.null,source.neq.email')):'—';$('#adminSystemStatus').textContent=`Signed in as ${currentProfile.full_name||currentSession.user.email} · ${currentProfile.role} · Booking & business follow-ups ${runtimeConfig.remindersEnabled?'active':'need CRON_SECRET'}`}
async function quoteTable(){
  if(!allowed('quotes'))return;
  const queries=[sb.from('quotes').select('*').order('created_at',{ascending:false}).limit(250)];
  if(allowed('bookings'))queries.push(sb.from('bookings').select('id,quote_id,status,starts_at').not('quote_id','is',null));
  const results=await Promise.all(queries);const {data,error}=results[0];
  if(error){$('#quoteTable').innerHTML=`<p>${esc(error.message)}</p>`;return}
  const bookingMap={};for(const b of results[1]?.data||[]){if(b.quote_id&&b.status!=='cancelled')bookingMap[b.quote_id]=b}
  quoteCache=(data||[]).map(q=>({...q,_booking:bookingMap[q.id]||null}));renderQuoteTable();
}

function renderQuoteTable(){
  const term=($('#quoteSearch')?.value||'').trim().toLowerCase(),status=$('#quoteFilterStatus')?.value||'all',service=$('#quoteFilterService')?.value||'all';
  const rows=quoteCache.filter(q=>{const hay=[q.customer_name,q.email,q.phone,q.postcode,q.service_key,q.admin_notes].join(' ').toLowerCase();return(!term||hay.includes(term))&&(status==='all'||q.status===status)&&(service==='all'||q.service_key===service)});
  const open=quoteCache.filter(q=>['new','reviewing'].includes(q.status)).length,approved=quoteCache.filter(q=>q.status==='approved').length;
  if($('#quoteSummary'))$('#quoteSummary').textContent=`${rows.length} shown · ${open} need review · ${approved} approved`;
  if(!rows.length){$('#quoteTable').innerHTML=crmEmpty('No quote requests match these filters.');return}
  $('#quoteTable').innerHTML=`<div class="table-scroll"><table class="admin-table crm-table"><thead><tr><th>Customer</th><th>Request</th><th>Pricing</th><th>Status</th><th>Notes</th><th>Actions</th></tr></thead><tbody>${rows.map(q=>{
    const i=q.inputs||{},discount=Number(q.promo_discount||0)+Number(q.reward_discount||0),booked=q._booking;
    return `<tr data-quote-row="${q.id}"><td><strong>${esc(q.customer_name)}</strong><br><a href="mailto:${esc(q.email)}">${esc(q.email)}</a>${q.phone?`<br><a href="tel:${esc(q.phone)}">${esc(q.phone)}</a>`:''}<br><small>${esc(q.postcode)}</small>${q.customer_id&&allowed('customers')?`<br><button class="text-action" data-view-customer="${q.customer_id}">Open customer</button>`:''}</td><td><strong>${esc(names[q.service_key]||q.service_key)}</strong><br><small>${dt(q.created_at)}</small><details class="crm-inline-details"><summary>Job details</summary><div>${i.units!=null?`Size/units: ${esc(i.units)}<br>`:''}${i.propertyType?`Property: ${esc(niceStatus(i.propertyType))}<br>`:''}${i.floors?`Floors: ${esc(i.floors)}<br>`:''}${i.access?`Access: ${esc(niceStatus(i.access))}<br>`:''}${i.urgency?`Urgency: ${esc(niceStatus(i.urgency))}<br>`:''}${i.frequency?`Frequency: ${esc(niceStatus(i.frequency))}<br>`:''}${i.notes?`<span class="crm-note">${esc(i.notes)}</span>`:''}</div></details>${(q.photo_paths||[]).length?`<button class="text-action" data-view-quote-photos="${q.id}">${q.photo_paths.length} private photo${q.photo_paths.length===1?'':'s'}</button>`:''}</td><td><small>Guide £${gbp(q.automatic_estimate)}</small>${discount?`<br><small>Discount £${gbp(discount)}</small>`:''}<br><label class="compact-field">Final £<input data-final type="number" step="0.01" value="${q.final_price??''}" placeholder="${q.automatic_estimate}"></label><label class="compact-field">Expires<input data-expires type="date" value="${q.expires_at?new Date(q.expires_at).toISOString().slice(0,10):''}"></label></td><td><select data-status>${['new','reviewing','sent','approved','declined','expired'].map(x=>`<option value="${x}" ${q.status===x?'selected':''}>${niceStatus(x)}</option>`).join('')}</select><div class="crm-chip ${q.customer_response==='accepted'?'success':q.customer_response==='declined'?'warning':''}">Customer: ${esc(niceStatus(q.customer_response||'pending'))}</div>${booked?`<div class="crm-chip success">Booked ${dt(booked.starts_at)}</div>`:''}</td><td><textarea data-customer-note rows="3" placeholder="Message shown to customer">${esc(q.customer_quote_note||'')}</textarea><textarea data-notes rows="3" placeholder="Internal Namdar note">${esc(q.admin_notes||'')}</textarea>${q.customer_response_note?`<small class="crm-note">Customer response note: ${esc(q.customer_response_note)}</small>`:''}</td><td><div class="crm-action-stack"><button class="primary-btn small" data-save-quote="${q.id}">Save</button>${allowed('bookings')&&!booked&&!['declined','expired'].includes(q.status)?`<button class="ghost-btn small" data-book-quote="${q.id}">${q.status==='approved'?'Schedule job':'Approve & schedule'}</button>`:''}${booked&&allowed('bookings')?`<button class="ghost-btn small" data-edit-booking="${booked.id}">Open booking</button>`:''}</div></td></tr>`}).join('')}</tbody></table></div>`;
  $$('[data-save-quote]').forEach(b=>b.onclick=()=>saveQuote(b.dataset.saveQuote,b));
  $$('[data-book-quote]').forEach(b=>b.onclick=()=>openBookingFromQuote(b.dataset.bookQuote));
  $$('[data-edit-booking]').forEach(b=>b.onclick=async()=>{if(!bookingCache.some(x=>x.id===b.dataset.editBooking))await bookingTable();openBookingEditor(b.dataset.editBooking)});
  $$('[data-view-customer]').forEach(b=>b.onclick=()=>openCustomerDetail(b.dataset.viewCustomer));$$('[data-view-quote-photos]').forEach(b=>b.onclick=()=>openQuotePhotos(b.dataset.viewQuotePhotos));
}
async function openQuotePhotos(id){const q=quoteCache.find(x=>x.id===id),paths=q?.photo_paths||[],dialog=$('#quotePhotosDialog'),body=$('#quotePhotosBody');if(!paths.length)return;body.innerHTML='<p>Loading private photos…</p>';dialog.showModal();const {data,error}=await sb.storage.from('customer-project-files').createSignedUrls(paths,1800);if(error){body.innerHTML=`<p>${esc(error.message)}</p>`;return}body.innerHTML=`<div class="admin-quote-photo-grid">${(data||[]).filter(x=>x?.signedUrl).map((x,i)=>`<a href="${esc(x.signedUrl)}" target="_blank" rel="noopener"><img src="${esc(x.signedUrl)}" alt="Quote photo ${i+1}"></a>`).join('')}</div>`}
async function saveQuote(id,btn){const row=document.querySelector(`[data-quote-row="${id}"]`);setBusy(btn,true,'Saving…');try{await api('/api/admin-quote-update',{method:'PATCH',body:JSON.stringify({id,finalPrice:row.querySelector('[data-final]').value,expiresAt:row.querySelector('[data-expires]').value,status:row.querySelector('[data-status]').value,customerNote:row.querySelector('[data-customer-note]').value,adminNotes:row.querySelector('[data-notes]').value})});btn.textContent='Saved ✓';await quoteTable();await counts()}catch(e){alert(e.message)}finally{setTimeout(()=>setBusy(btn,false),500)}}

async function loadBookingStaff(force=false){
  if(bookingStaffCache.length&&!force){populateBookingStaffControls();return bookingStaffCache}
  try{const d=await api('/api/admin-booking-staff');bookingStaffCache=d.staff||[]}catch(e){console.warn('Could not load booking staff',e);bookingStaffCache=[]}
  populateBookingStaffControls();return bookingStaffCache
}
function staffName(id){const x=bookingStaffCache.find(s=>s.id===id);return x?(x.full_name||x.email||'Team member'):'Unassigned'}
function staffRoleLabel(id){const x=bookingStaffCache.find(s=>s.id===id);return x?.job_title||x?.role||''}
function populateBookingStaffControls(){
  const opts=bookingStaffCache.map(x=>`<option value="${x.id}">${esc(x.full_name||x.email)}${x.job_title?` · ${esc(x.job_title)}`:''}</option>`).join('');
  const editor=$('#editBookingStaff');if(editor){const current=editor.value;editor.innerHTML=`<option value="">Unassigned</option>${opts}`;if([...editor.options].some(o=>o.value===current))editor.value=current}
  const filter=$('#calendarStaffFilter');if(filter){const current=filter.value||'all';filter.innerHTML=`<option value="all">All team</option><option value="unassigned">Unassigned</option>${opts}`;filter.value=[...filter.options].some(o=>o.value===current)?current:'all'}
}
async function bookingTable(){
  if(!allowed('bookings'))return;subscriptionAdminTable().catch(console.error);
  const [bookingResult,,changeResult]=await Promise.all([sb.from('bookings').select('*').order('starts_at',{ascending:false}).limit(500),loadBookingStaff(),api('/api/admin-booking-changes?status=pending',{method:'GET'}).catch(()=>({requests:[]}))]);const {data,error}=bookingResult;if(error){$('#bookingTable').innerHTML=`<p>${esc(error.message)}</p>`;$('#bookingCalendar').innerHTML=crmEmpty(error.message);return}
  const ids=[...new Set((data||[]).map(b=>b.quote_id).filter(Boolean))];let quotes=[];
  if(ids.length){const r=await sb.from('quotes').select('id,customer_id,customer_name,email,phone,postcode,service_key,automatic_estimate,final_price,status').in('id',ids);quotes=r.data||[]}
  const qm=Object.fromEntries(quotes.map(q=>[q.id,q]));bookingCache=(data||[]).map(b=>({...b,_quote:qm[b.quote_id]||null}));bookingChangeCache=changeResult?.requests||[];renderBookingChangeRequests();renderBookingTable();renderBookingCalendar();
}
function renderBookingChangeRequests(){
  const root=$('#bookingChangeRequests'),summary=$('#bookingChangeSummary');if(!root)return;const rows=(bookingChangeCache||[]).filter(r=>r.status==='pending');if(summary)summary.textContent=`${rows.length} pending`;
  if(!rows.length){root.innerHTML=crmEmpty('No customer booking change requests are waiting for review.');return}
  root.innerHTML=`<div class="table-scroll"><table class="admin-table crm-table"><thead><tr><th>Customer</th><th>Current booking</th><th>Request</th><th>Note</th><th>Action</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.customer?.name||'Customer')}</strong><br><small>${esc(r.serviceLabel||'Namdar service')}</small>${r.customer?.email?`<br><a href="mailto:${esc(r.customer.email)}">${esc(r.customer.email)}</a>`:''}</td><td><strong>${dt(r.booking?.startsAt)}</strong><br><small>${esc(r.booking?.address||'')}</small></td><td><span class="crm-chip warning">${esc(r.type==='cancel'?'Cancellation':'Reschedule')}</span>${r.type==='reschedule'?`<br><strong>${dt(r.requestedStartsAt)}</strong>`:''}<br><small>Requested ${dt(r.createdAt)}</small></td><td>${r.reason?esc(r.reason):'<span class="muted">No note</span>'}</td><td><button class="primary-btn small" type="button" data-review-booking-change="${esc(r.id)}">Review</button></td></tr>`).join('')}</tbody></table></div>`;
  $$('[data-review-booking-change]').forEach(b=>b.onclick=()=>openBookingChangeReview(b.dataset.reviewBookingChange));
}
function openBookingChangeReview(id){
  const r=bookingChangeCache.find(x=>x.id===id);if(!r)return;$('#bookingChangeReviewId').value=r.id;$('#bookingChangeAdminNote').value='';$('#bookingChangeReviewTitle').textContent=r.type==='cancel'?'Review cancellation request':'Review reschedule request';$('#bookingChangeReviewContext').innerHTML=`<strong>${esc(r.customer?.name||'Customer')} · ${esc(r.serviceLabel||'Namdar service')}</strong><br><span>Current: ${esc(dt(r.booking?.startsAt))}</span>${r.type==='reschedule'?`<br><span>Requested: <strong>${esc(dt(r.requestedStartsAt))}</strong></span>`:'<br><span><strong>Customer wants to cancel this appointment.</strong></span>'}<br><small>${esc(r.booking?.address||'')}</small>${r.reason?`<div class="crm-note"><strong>Customer note:</strong> ${esc(r.reason)}</div>`:''}`;$('#bookingChangeReviewStatus').textContent='';$('#bookingChangeReview').showModal();
}
async function reviewBookingChange(action){
  const btn=action==='approve'?$('#approveBookingChange'):$('#declineBookingChange'),id=$('#bookingChangeReviewId').value,note=$('#bookingChangeAdminNote').value.trim();if(action==='decline'&&!note&&!confirm('Decline this request without a note to the customer?'))return;if(action==='approve'&&!confirm('Approve this customer booking request and update the live booking?'))return;setBusy(btn,true,action==='approve'?'Approving…':'Declining…');try{const d=await api('/api/admin-booking-changes',{method:'POST',body:JSON.stringify({requestId:id,action,note})});$('#bookingChangeReviewStatus').textContent=d.message||'Saved.';await Promise.all([bookingTable(),counts()]);setTimeout(()=>$('#bookingChangeReview').close(),650)}catch(e){$('#bookingChangeReviewStatus').textContent=e.message}finally{setBusy(btn,false)}
}
function bookingPrice(b){const q=b._quote||{};const v=q.final_price??q.automatic_estimate;return v==null?'—':`£${gbp(v)}`}
function renderBookingTable(){
  const term=($('#bookingSearch')?.value||'').trim().toLowerCase(),status=$('#bookingFilterStatus')?.value||'all',when=$('#bookingFilterWhen')?.value||'all',now=Date.now();
  const rows=bookingCache.filter(b=>{const q=b._quote||{},staff=staffName(b.assigned_staff_id),hay=[q.customer_name,q.email,q.phone,q.postcode,q.service_key,b.address,b.status,b.payment_status,staff].join(' ').toLowerCase(),t=new Date(b.starts_at).getTime();return(!term||hay.includes(term))&&(status==='all'||b.status===status)&&(when==='all'||(when==='upcoming'?t>=now:t<now))}).sort((a,b)=>{const aa=['pending','confirmed'].includes(a.status)&&new Date(a.starts_at).getTime()>=now,bb=['pending','confirmed'].includes(b.status)&&new Date(b.starts_at).getTime()>=now;if(aa!==bb)return aa?-1:1;return aa?new Date(a.starts_at)-new Date(b.starts_at):new Date(b.starts_at)-new Date(a.starts_at)});
  const upcoming=bookingCache.filter(b=>['pending','confirmed'].includes(b.status)&&new Date(b.starts_at).getTime()>=now).length,pending=bookingCache.filter(b=>b.status==='pending').length;
  if($('#bookingSummary'))$('#bookingSummary').textContent=`${rows.length} shown · ${upcoming} upcoming · ${pending} pending`;
  if(!rows.length){$('#bookingTable').innerHTML=crmEmpty('No bookings match these filters.');return}
  $('#bookingTable').innerHTML=`<div class="table-scroll"><table class="admin-table crm-table"><thead><tr><th>Customer / service</th><th>Visit</th><th>Team</th><th>Address</th><th>Price</th><th>Status</th><th>Payment</th><th>Actions</th></tr></thead><tbody>${rows.map(b=>{const q=b._quote||{},past=new Date(b.starts_at).getTime()<now&&!['completed','cancelled'].includes(b.status);return `<tr data-booking-row="${b.id}"><td><strong>${esc(q.customer_name||'Customer')}</strong><br><small>${esc(names[q.service_key]||q.service_key||'Booking')}</small>${q.email?`<br><a href="mailto:${esc(q.email)}">${esc(q.email)}</a>`:''}${q.phone?`<br><a href="tel:${esc(q.phone)}">${esc(q.phone)}</a>`:''}${q.customer_id&&allowed('customers')?`<br><button class="text-action" data-view-customer="${q.customer_id}">Open customer</button>`:''}</td><td><strong>${dt(b.starts_at)}</strong><br><small>${Math.max(0,Math.round((new Date(b.ends_at)-new Date(b.starts_at))/60000))} min</small>${past?'<div class="crm-chip warning">Past due</div>':''}</td><td><strong>${esc(staffName(b.assigned_staff_id))}</strong>${b.assigned_staff_id&&staffRoleLabel(b.assigned_staff_id)?`<br><small>${esc(staffRoleLabel(b.assigned_staff_id))}</small>`:''}</td><td>${esc(b.address||'—')}</td><td><strong>${esc(bookingPrice(b))}</strong></td><td><select data-bstatus>${['pending','confirmed','completed','cancelled'].map(x=>`<option value="${x}" ${b.status===x?'selected':''}>${niceStatus(x)}</option>`).join('')}</select><div class="staff-field-chip">Field: ${niceStatus(b.work_status||'scheduled')}</div></td><td><span class="crm-chip ${b.payment_status==='paid'?'success':b.payment_status==='deposit_paid'?'warning':''}">${esc(niceStatus(b.payment_status||'unpaid'))}</span>${allowed('payments')?'<br><button class="text-action" data-open-payments>Manage payments</button>':''}</td><td><div class="crm-action-stack"><button class="primary-btn small" data-save-booking="${b.id}">Save</button><button class="ghost-btn small" data-schedule-booking="${b.id}">Open job</button></div></td></tr>`}).join('')}</tbody></table></div>`;
  $$('[data-save-booking]').forEach(b=>b.onclick=()=>saveBooking(b.dataset.saveBooking,b));$$('[data-schedule-booking]').forEach(b=>b.onclick=()=>openBookingEditor(b.dataset.scheduleBooking));$$('[data-view-customer]').forEach(b=>b.onclick=()=>openCustomerDetail(b.dataset.viewCustomer));$$('[data-view-quote-photos]').forEach(b=>b.onclick=()=>openQuotePhotos(b.dataset.viewQuotePhotos));$$('[data-open-payments]').forEach(b=>b.onclick=()=>document.querySelector('[data-tab="payments"]')?.click());
}
async function saveBooking(id,btn){const row=document.querySelector(`[data-booking-row="${id}"]`);setBusy(btn,true,'Saving…');try{await api('/api/admin-booking-update',{method:'PATCH',body:JSON.stringify({id,status:row.querySelector('[data-bstatus]').value})});btn.textContent='Saved ✓';await bookingTable();await counts()}catch(e){alert(e.message)}finally{setTimeout(()=>setBusy(btn,false),500)}}
function calendarDayStart(v){const d=new Date(v);d.setHours(0,0,0,0);return d}
function calendarWeekStart(v){const d=calendarDayStart(v),day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return d}
function sameDay(a,b){return localDateValue(a)===localDateValue(b)}
function calendarFilteredBookings(){const f=$('#calendarStaffFilter')?.value||'all';return bookingCache.filter(b=>f==='all'||(f==='unassigned'?!b.assigned_staff_id:b.assigned_staff_id===f))}
function calendarEvent(b,compact=false){const q=b._quote||{},start=new Date(b.starts_at),end=new Date(b.ends_at),time=`${localTimeValue(start)}–${localTimeValue(end)}`,customer=q.customer_name||'Customer',service=names[q.service_key]||q.service_key||'Booking',staff=staffName(b.assigned_staff_id);return `<button type="button" class="diary-event ${esc(b.status)} ${compact?'compact':''}" data-calendar-booking="${b.id}" title="${esc(`${time} · ${customer} · ${service} · ${staff}`)}"><span class="diary-event-time">${esc(time)}</span><strong>${esc(customer)}</strong><span>${esc(service)}</span>${compact?'':`<small>${esc(staff)} · ${esc(bookingPrice(b))}</small>`}</button>`}
function calendarTitleFor(date,view){const d=new Date(date);if(view==='month')return d.toLocaleDateString('en-GB',{month:'long',year:'numeric'});if(view==='day')return d.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'});const start=calendarWeekStart(d),end=new Date(start);end.setDate(end.getDate()+6);const left=start.toLocaleDateString('en-GB',{day:'numeric',month:start.getMonth()===end.getMonth()?undefined:'short'}),right=end.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});return `${left} – ${right}`}
function renderBookingCalendar(){
  const root=$('#bookingCalendar');if(!root)return;const view=bookingCalendarView,date=calendarDayStart(bookingCalendarDate),events=calendarFilteredBookings().sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at));$('#calendarTitle').textContent=calendarTitleFor(date,view);$$('[data-calendar-view]').forEach(b=>b.classList.toggle('active',b.dataset.calendarView===view));
  if(view==='month'){
    const first=new Date(date.getFullYear(),date.getMonth(),1),start=calendarWeekStart(first),last=new Date(date.getFullYear(),date.getMonth()+1,0),end=new Date(calendarWeekStart(last));end.setDate(end.getDate()+6);const days=[];for(let d=new Date(start);d<=end;d.setDate(d.getDate()+1))days.push(new Date(d));
    root.innerHTML=`<div class="diary-month"><div class="diary-weekdays">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<div>${x}</div>`).join('')}</div><div class="diary-month-grid">${days.map(d=>{const dayEvents=events.filter(b=>sameDay(b.starts_at,d)),outside=d.getMonth()!==date.getMonth(),today=sameDay(d,new Date());return `<div class="diary-day-cell ${outside?'outside':''} ${today?'today':''}"><div class="diary-day-number">${d.getDate()}</div><div class="diary-day-events">${dayEvents.slice(0,4).map(b=>calendarEvent(b,true)).join('')}${dayEvents.length>4?`<button class="diary-more" type="button" data-calendar-day="${localDateValue(d)}">+${dayEvents.length-4} more</button>`:''}</div></div>`}).join('')}</div></div>`;
  }else if(view==='week'){
    const start=calendarWeekStart(date),days=[0,1,2,3,4,5,6].map(i=>{const d=new Date(start);d.setDate(d.getDate()+i);return d});root.innerHTML=`<div class="diary-week-grid">${days.map(d=>{const dayEvents=events.filter(b=>sameDay(b.starts_at,d)),today=sameDay(d,new Date());return `<section class="diary-week-day ${today?'today':''}"><header><strong>${d.toLocaleDateString('en-GB',{weekday:'short'})}</strong><span>${d.toLocaleDateString('en-GB',{day:'numeric',month:'short'})}</span></header><div class="diary-week-events">${dayEvents.length?dayEvents.map(b=>calendarEvent(b)).join(''):'<span class="diary-empty-day">No jobs</span>'}</div></section>`}).join('')}</div>`;
  }else{
    const dayEvents=events.filter(b=>sameDay(b.starts_at,date));let minHour=7,maxHour=19;if(dayEvents.length){minHour=Math.min(minHour,...dayEvents.map(b=>new Date(b.starts_at).getHours()));maxHour=Math.max(maxHour,...dayEvents.map(b=>new Date(b.starts_at).getHours()+1))}const hours=[];for(let h=Math.max(0,minHour);h<=Math.min(23,maxHour);h++)hours.push(h);root.innerHTML=`<div class="diary-day-timeline">${hours.map(h=>{const hs=dayEvents.filter(b=>new Date(b.starts_at).getHours()===h);return `<div class="diary-hour-row"><time>${String(h).padStart(2,'0')}:00</time><div>${hs.map(b=>calendarEvent(b)).join('')}</div></div>`}).join('')}${!dayEvents.length?'<div class="crm-empty">No jobs scheduled for this day.</div>':''}</div>`;
  }
  $$('[data-calendar-booking]').forEach(b=>b.onclick=()=>openBookingEditor(b.dataset.calendarBooking));$$('[data-calendar-day]').forEach(b=>b.onclick=()=>{bookingCalendarDate=new Date(`${b.dataset.calendarDay}T12:00:00`);bookingCalendarView='day';renderBookingCalendar()});
}
function moveCalendar(direction){const d=new Date(bookingCalendarDate);if(bookingCalendarView==='month')d.setMonth(d.getMonth()+direction);else if(bookingCalendarView==='week')d.setDate(d.getDate()+7*direction);else d.setDate(d.getDate()+direction);bookingCalendarDate=d;renderBookingCalendar()}
