async function saveInvoiceEditor(send=false){const btn=send?$('#sendInvoiceEditor'):$('#saveInvoiceEditor');setBusy(btn,true,send?'Saving & sending…':'Saving…');try{const invoiceId=$('#invoiceEditorId').value,due=$('#invoiceDueAt').value;await api('/api/admin-payments',{method:'POST',body:JSON.stringify({action:'update_invoice',invoiceId,dueAt:due?new Date(`${due}T12:00:00`).toISOString():null,notes:$('#invoiceNotes').value.trim()})});if(send)await api('/api/admin-payments',{method:'POST',body:JSON.stringify({action:'send_invoice',invoiceId})});$('#invoiceEditorStatus').textContent=send?'Invoice saved and emailed.':'Invoice saved.';await paymentsTools();setTimeout(()=>$('#invoiceEditor').close(),650)}catch(e){$('#invoiceEditorStatus').textContent=e.message}finally{setBusy(btn,false)}}
