  const rows=feedbackCache.filter(x=>{const q=x.quote||{},hay=[q.customer_name,q.email,q.phone,q.postcode,q.service_key,x.comments,x.admin_notes,x.status].join(' ').toLowerCase();return(!term||hay.includes(term))&&(filter==='all'||x.status===filter)});$('#feedbackSummary').textContent=`${rows.length} shown · ${attention} need attention`;
