async function content(){if(!allowed('content'))return;const [{data:offers},{data:jobs}]=await Promise.all([sb.from('offers').select('*').order('starts_at',{ascending:false}),sb.from('portfolio_jobs').select('*').order('created_at',{ascending:false})]);$('#offerList').innerHTML=offers?.length?`<table class="admin-table"><tbody>${offers.map(o=>`<tr><td><strong>${esc(o.title)}</strong><br><small>${esc(o.body||'')}</small></td><td>${o.active?'Active':'Inactive'}</td><td><button data-toggle-offer="${o.id}" data-active="${o.active}">${o.active?'Deactivate':'Activate'}</button> <button data-delete-offer="${o.id}">Delete</button></td></tr>`).join('')}</tbody></table>`:'<p>No offers yet.</p>';$('#jobList').innerHTML=jobs?.length?`<table class="admin-table"><tbody>${jobs.map(j=>`<tr><td>${Array.isArray(j.image_urls)&&j.image_urls[0]?`<img class="admin-thumb" src="${esc(j.image_urls[0])}" alt="">`:''}</td><td><strong>${esc(j.title)}</strong><br><small>${esc(j.location_label||'')} · ${j.published?'Published':'Draft'}</small></td><td><button data-delete-job="${j.id}">Delete</button></td></tr>`).join('')}</tbody></table>`:'<p>No jobs yet.</p>';$$('[data-toggle-offer]').forEach(b=>b.onclick=async()=>{await sb.from('offers').update({active:b.dataset.active!=='true'}).eq('id',b.dataset.toggleOffer);content()});$$('[data-delete-offer]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this offer?')){await sb.from('offers').delete().eq('id',b.dataset.deleteOffer);content()}});$$('[data-delete-job]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this job?')){await sb.from('portfolio_jobs').delete().eq('id',b.dataset.deleteJob);content()}})}
async function uploadJobImages(files){const urls=[];for(const file of files){const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'-'),path=`${Date.now()}-${Math.random().toString(36).slice(2)}-${safe}`;const {error}=await sb.storage.from('job-images').upload(path,file);if(error)throw error;const {data}=sb.storage.from('job-images').getPublicUrl(path);if(data?.publicUrl)urls.push(data.publicUrl)}return urls}
async function saveOffer(){setBusy($('#saveOffer'),true,'Adding…');try{const body={title:$('#offerAdminTitle').value.trim(),body:$('#offerAdminText').value.trim()||null,discount_type:$('#offerType').value,discount_value:$('#offerValue').value?Number($('#offerValue').value):null,starts_at:$('#offerStart').value?new Date($('#offerStart').value).toISOString():null,ends_at:$('#offerEnd').value?new Date($('#offerEnd').value).toISOString():null,active:$('#offerActive').checked};if(!body.title)throw new Error('Add a headline.');const {error}=await sb.from('offers').insert(body);if(error)throw error;await content()}catch(e){alert(e.message)}finally{setBusy($('#saveOffer'),false)}}
