    const d=await api('/api/admin-users?scope=customers');customerCache=d.users||[];const customers=customerCache.filter(x=>x.role==='customer');$('#projectCustomer').innerHTML=customers.map(p=>`<option value="${p.id}">${esc(p.full_name||p.email)} · ${esc(p.email||'')}</option>`).join('');
