async function deleteUser(){const id=$('#editUserId').value,name=$('#editUserEmail').value;if(!id||!confirm(`Permanently delete ${name}? This removes their authentication account and linked customer profile. This cannot be undone.`))return;try{await api('/api/admin-users',{method:'DELETE',body:JSON.stringify({id})});$('#userEditor').close();await customerTools();await staffTools()}catch(e){alert(e.message)}}
async function staffTools(){if(!allowed('staff'))return;try{const d=await api('/api/admin-users?scope=staff');staffAdminCache=d.users||[];const rows=staffAdminCache.filter(x=>['staff','admin'].includes(x.role));$('#staffTable').innerHTML=rows.length?`<table class="admin-table"><thead><tr><th>Staff</th><th>Role</th><th>Job title</th><th>Permissions</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.full_name||x.email)}<br><small>${esc(x.email||'')}</small></td><td>${esc(x.role)}</td><td>${esc(x.staff_access?.job_title||'—')}</td><td><small>${x.role==='admin'?'All':Object.entries(x.staff_access?.permissions||{}).filter(([,v])=>v).map(([k])=>k).join(', ')||'None'}</small></td><td><button class="ghost-btn small" data-edit-staff="${x.id}">Edit</button></td></tr>`).join('')}</tbody></table>`:'<p>No staff users.</p>';$$('[data-edit-staff]').forEach(b=>b.onclick=()=>openUserEditor(staffAdminCache.find(x=>x.id===b.dataset.editStaff),'staff'));if(allowed('bookings'))await loadBookingStaff(true);}catch(e){$('#staffTable').innerHTML=`<p>${esc(e.message)}</p>`}}
async function loyaltyTools(){if(!allowed('loyalty'))return;const [{data:rules},{data:rewards},{data:promos}]=await Promise.all([sb.from('loyalty_rules').select('*').order('created_at'),sb.from('rewards').select('*').order('created_at'),sb.from('promo_codes').select('*').order('created_at',{ascending:false})]);$('#loyaltyRules').innerHTML=(rules||[]).map(r=>`<div class="inline-editor" data-rule="${r.id}"><input data-service value="${esc(r.service_key||'all')}" placeholder="service"><input data-event value="${esc(r.event_key)}"><input data-points type="number" value="${r.points}"><input data-desc value="${esc(r.description||'')}"><label><input data-active type="checkbox" ${r.active?'checked':''}> active</label><button data-save-rule="${r.id}">Save</button><button data-del-rule="${r.id}">×</button></div>`).join('');$('#rewardsAdmin').innerHTML=(rewards||[]).map(r=>`<div class="inline-editor" data-reward="${r.id}"><input data-title value="${esc(r.title)}"><input data-cost type="number" value="${r.points_cost}"><select data-type><option value="fixed" ${r.discount_type==='fixed'?'selected':''}>£ off</option><option value="percent" ${r.discount_type==='percent'?'selected':''}>% off</option></select><input data-value type="number" step="0.01" value="${r.discount_value}"><input data-service value="${esc(r.service_key||'all')}"><label><input data-active type="checkbox" ${r.active?'checked':''}> active</label><button data-save-reward="${r.id}">Save</button><button data-del-reward="${r.id}">×</button></div>`).join('');$('#promoAdmin').innerHTML=(promos||[]).map(p=>`<div class="inline-editor" data-promo="${p.id}"><input data-code value="${esc(p.code)}"><select data-type><option value="percent" ${p.discount_type==='percent'?'selected':''}>%</option><option value="fixed" ${p.discount_type==='fixed'?'selected':''}>£</option></select><input data-value type="number" step="0.01" value="${p.discount_value}"><input data-service value="${esc(p.service_key||'all')}"><input data-max type="number" value="${p.max_uses??''}" placeholder="max uses"><label><input data-active type="checkbox" ${p.active?'checked':''}> active</label><button data-save-promo="${p.id}">Save</button><button data-del-promo="${p.id}">×</button></div>`).join('');bindLoyaltyActions();await customerPoints()}
function bindLoyaltyActions(){$$('[data-save-rule]').forEach(b=>b.onclick=async()=>{const el=document.querySelector(`[data-rule="${b.dataset.saveRule}"]`);await sb.from('loyalty_rules').update({service_key:el.querySelector('[data-service]').value==='all'?null:el.querySelector('[data-service]').value,event_key:el.querySelector('[data-event]').value,points:Number(el.querySelector('[data-points]').value),description:el.querySelector('[data-desc]').value,active:el.querySelector('[data-active]').checked,updated_at:new Date().toISOString()}).eq('id',b.dataset.saveRule);loyaltyTools()});$$('[data-del-rule]').forEach(b=>b.onclick=async()=>{if(confirm('Delete rule?')){await sb.from('loyalty_rules').delete().eq('id',b.dataset.delRule);loyaltyTools()}});$$('[data-save-reward]').forEach(b=>b.onclick=async()=>{const e=document.querySelector(`[data-reward="${b.dataset.saveReward}"]`);await sb.from('rewards').update({title:e.querySelector('[data-title]').value,points_cost:Number(e.querySelector('[data-cost]').value),discount_type:e.querySelector('[data-type]').value,discount_value:Number(e.querySelector('[data-value]').value),service_key:e.querySelector('[data-service]').value==='all'?null:e.querySelector('[data-service]').value,active:e.querySelector('[data-active]').checked}).eq('id',b.dataset.saveReward);loyaltyTools()});$$('[data-del-reward]').forEach(b=>b.onclick=async()=>{if(confirm('Delete reward?')){await sb.from('rewards').delete().eq('id',b.dataset.delReward);loyaltyTools()}});$$('[data-save-promo]').forEach(b=>b.onclick=async()=>{const e=document.querySelector(`[data-promo="${b.dataset.savePromo}"]`);await sb.from('promo_codes').update({code:e.querySelector('[data-code]').value.toUpperCase(),discount_type:e.querySelector('[data-type]').value,discount_value:Number(e.querySelector('[data-value]').value),service_key:e.querySelector('[data-service]').value==='all'?null:e.querySelector('[data-service]').value,max_uses:e.querySelector('[data-max]').value?Number(e.querySelector('[data-max]').value):null,active:e.querySelector('[data-active]').checked,updated_at:new Date().toISOString()}).eq('id',b.dataset.savePromo);loyaltyTools()});$$('[data-del-promo]').forEach(b=>b.onclick=async()=>{if(confirm('Delete promo code?')){await sb.from('promo_codes').delete().eq('id',b.dataset.delPromo);loyaltyTools()}})}
async function customerPoints(){const {data}=await sb.from('profiles').select('id,full_name,email,points_balance').eq('role','customer').order('full_name');$('#customerPoints').innerHTML=data?.length?`<table class="admin-table"><thead><tr><th>Customer</th><th>Balance</th><th>Adjustment</th></tr></thead><tbody>${data.map(p=>`<tr><td>${esc(p.full_name||p.email)}</td><td>${p.points_balance||0}</td><td><input data-point-value="${p.id}" type="number" placeholder="+/- points"><input data-point-reason="${p.id}" placeholder="reason"><button data-add-points="${p.id}">Apply</button></td></tr>`).join('')}</tbody></table>`:'<p>No customers.</p>';$$('[data-add-points]').forEach(b=>b.onclick=async()=>{const pts=Number(document.querySelector(`[data-point-value="${b.dataset.addPoints}"]`).value),reason=document.querySelector(`[data-point-reason="${b.dataset.addPoints}"]`).value.trim()||'Admin adjustment';if(!Number.isFinite(pts)||pts===0)return alert('Enter points to add or remove.');const {error}=await sb.from('loyalty_ledger').insert({customer_id:b.dataset.addPoints,points:pts,reason,created_by:currentSession.user.id});if(error)alert(error.message);else loyaltyTools()})}
async function newsletterTools(){if(!allowed('newsletter'))return;const {data,error}=await sb.from('newsletter_subscribers').select('*').order('created_at',{ascending:false});if(error){$('#campaignStatus').textContent=error.message;return}const active=(data||[]).filter(x=>x.status==='subscribed');$('#newsletterStats').textContent=`${active.length} active · ${(data||[]).length} total`;$('#subscriberList').innerHTML=data?.length?`<table class="admin-table"><tbody>${data.map(x=>`<tr><td>${esc(x.email)}</td><td>${esc(x.full_name||'—')}</td><td>${esc(x.status)}</td><td>${new Date(x.consent_at).toLocaleDateString('en-GB')}</td></tr>`).join('')}</tbody></table>`:'<p>No subscribers.</p>'}
async function sendCampaign(){if(!confirm('Send this newsletter to all active subscribers?'))return;setBusy($('#sendCampaign'),true,'Sending…');try{const d=await api('/api/admin-newsletter-send',{method:'POST',body:JSON.stringify({subject:$('#campaignSubject').value.trim(),body:$('#campaignBody').value.trim()})});$('#campaignStatus').textContent=`Sent ${d.sent} of ${d.total}.`}catch(e){$('#campaignStatus').textContent=e.message}finally{setBusy($('#sendCampaign'),false)}}
function setAreaEditorStatus(message='',ok=false){const el=$('#areaFormStatus');if(!el)return;el.textContent=message;el.classList.toggle('success',!!ok);el.classList.toggle('error',!!message&&!ok)}
function setAreaLocateStatus(message='',ok=false){const el=$('#areaLocateStatus');if(!el)return;el.textContent=message||'Use a postcode for an accurate centre, or click the map.';el.classList.toggle('success',!!ok);el.classList.toggle('error',!!message&&!ok)}
function setAreaBoundaryStatus(message='',ok=false){const el=$('#areaBoundaryStatus');if(!el)return;const n=areaBoundaryPoints.length;el.textContent=message||(n?`${n} boundary point${n===1?'':'s'} selected${n>=3?' · drag any numbered point to fine-tune · ready to save':''}.`:'No custom boundary yet. Start drawing to add points.');el.classList.toggle('success',!!ok);el.classList.toggle('error',!!message&&!ok)}
function setAreaAdminStatus(message='',ok=false){const el=$('#areaAdminStatus');if(!el)return;el.textContent=message;el.classList.toggle('success',!!ok);el.classList.toggle('error',!!message&&!ok)}
function areaNum(id){const raw=$(id)?.value?.trim()||'',n=Number(raw);return raw!==''&&Number.isFinite(n)?n:null}
function areaDraftPoint(){const latitude=areaNum('#areaLat'),longitude=areaNum('#areaLng'),radius=areaNum('#areaRadius');return{latitude,longitude,radius}}
function areaHaversineKm(lat1,lng1,lat2,lng2){const r=6371,toRad=v=>v*Math.PI/180,dLat=toRad(lat2-lat1),dLng=toRad(lng2-lng1),a=Math.sin(dLat/2)**2+Math.cos(toRad(lat1))*Math.cos(toRad(lat2))*Math.sin(dLng/2)**2;return 2*r*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))}
function cleanAreaRule(v=''){return String(v||'').trim().toUpperCase().replace(/\s+/g,'').replace(/[^A-Z0-9*]/g,'')}
function parseAreaRules(v=''){const out=[],seen=new Set();for(const raw of String(v||'').split(/[\n,;]+/)){const display=raw.trim().toUpperCase();if(!display)continue;const key=cleanAreaRule(display);if(!key||seen.has(key))continue;seen.add(key);out.push(display)}return out}
function areaPostcodeParts(value=''){const full=String(value||'').trim().toUpperCase().replace(/\s+/g,''),outward=full.length>3?full.slice(0,-3):full,sector=full.length>3?outward+full.slice(-3,-2):outward;return{full,outward,sector}}
function matchAreaPostcodeRule(postcode,rules=[]){const p=areaPostcodeParts(postcode);let best=null;for(const raw of rules||[]){const rule=cleanAreaRule(raw);if(!rule)continue;let matched=false,rank=0,type='';if(rule.endsWith('*')){const prefix=rule.slice(0,-1);matched=!!prefix&&p.full.startsWith(prefix);rank=10+Math.min(prefix.length,8);type='wildcard'}else if(rule===p.full){matched=true;rank=40;type='full postcode'}else if(rule===p.sector){matched=true;rank=30;type='postcode sector'}else if(rule===p.outward){matched=true;rank=20;type='postcode district'}if(matched&&(!best||rank>best.rank))best={rule:raw,rank,type}}return best}
function pointInAreaRing(lng,lat,ring=[]){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const xi=Number(ring[i]?.[0]),yi=Number(ring[i]?.[1]),xj=Number(ring[j]?.[0]),yj=Number(ring[j]?.[1]);if(![xi,yi,xj,yj].every(Number.isFinite))continue;const hit=((yi>lat)!==(yj>lat))&&(lng<(xj-xi)*(lat-yi)/((yj-yi)||1e-12)+xi);if(hit)inside=!inside}return inside}
function areaGeometry(value){if(!value||typeof value!=='object')return null;return value.type==='Feature'?value.geometry||null:value}
function boundaryPointsFromGeojson(value){const g=areaGeometry(value);if(!g||g.type!=='Polygon'||!Array.isArray(g.coordinates?.[0]))return[];const ring=g.coordinates[0].map(x=>[Number(x[1]),Number(x[0])]).filter(x=>x.every(Number.isFinite));if(ring.length>1&&ring[0][0]===ring.at(-1)[0]&&ring[0][1]===ring.at(-1)[1])ring.pop();return ring}
function boundaryGeojson(){if(areaBoundaryPoints.length<3)return null;const ring=areaBoundaryPoints.map(([lat,lng])=>[Number(lng.toFixed(6)),Number(lat.toFixed(6))]);ring.push([...ring[0]]);return{type:'Polygon',coordinates:[ring]}}
function selectedAreaServices(){return $('#areaAllServices')?.checked?[]:$$('[data-area-service]:checked').map(x=>x.dataset.areaService)}
function areaServicesLabel(keys=[]){return Array.isArray(keys)&&keys.length?keys.map(x=>names[x]||x).join(', '):'All services'}
function serviceScopesOverlap(a=[],b=[]){const aa=Array.isArray(a)?a:[],bb=Array.isArray(b)?b:[];return !aa.length||!bb.length||aa.some(x=>bb.includes(x))}
function draftServiceApplies(service){const keys=selectedAreaServices();return !service||service==='all'||!keys.length||keys.includes(service)}
function setAreaServices(keys=[]){const list=Array.isArray(keys)?keys.filter(x=>names[x]):[],all=!list.length;if($('#areaAllServices'))$('#areaAllServices').checked=all;$$('[data-area-service]').forEach(x=>{x.checked=all||list.includes(x.dataset.areaService);x.disabled=all})}
function updateAreaServiceUI(){const all=$('#areaAllServices')?.checked!==false;$$('[data-area-service]').forEach(x=>{x.disabled=all;if(all)x.checked=true});updateAreaDraftSummary();renderAreaConflicts()}
function clearAreaBoundaryLayers(){if(areaDraftPolygon){areaDraftPolygon.remove();areaDraftPolygon=null}for(const l of areaBoundaryVertexLayers)l.remove();areaBoundaryVertexLayers=[]}
function clearAreaAdminLayer(){if(areaAdminBoundaryLayer){areaAdminBoundaryLayer.remove();areaAdminBoundaryLayer=null}}
function clearAreaAdminBrowseLayer(){if(areaAdminBrowseLayer){areaAdminBrowseLayer.remove();areaAdminBrowseLayer=null}areaAdminBrowseKey=''}
function clearAreaDraftPreview(){if(areaDraftMarker){areaDraftMarker.remove();areaDraftMarker=null}if(areaDraftCircle){areaDraftCircle.remove();areaDraftCircle=null}clearAreaBoundaryLayers();clearAreaAdminLayer();clearAreaAdminBrowseLayer()}
function adminAreaFilterMatch(a,filter){if(filter==='all')return true;if(filter==='london')return !!a.isLondon;if(filter==='england')return a.nation==='England';if(filter==='wales')return a.nation==='Wales';if(filter==='scotland')return a.nation==='Scotland';if(filter==='northern-ireland')return a.nation==='Northern Ireland';return true}
function visibleAdminAreas(){const q=($('#areaAdminSearch')?.value||'').trim().toLowerCase(),filter=$('#areaAdminFilter')?.value||'london';return areaAdminCatalog.filter(a=>adminAreaFilterMatch(a,filter)&&(!q||a.name.toLowerCase().includes(q)||a.code.toLowerCase().includes(q)))}
function renderAreaConflicts(){const el=$('#areaConflictStatus');if(!el)return;el.textContent='';el.className='coverage-conflict-status';if($('#areaCoverageMode')?.value!=='administrative'||!areaAdminSelected.size)return;const services=selectedAreaServices(),priority=areaNum('#areaPriority')??100,conflicts=[];for(const a of areaCache||[]){if(a.id===editingAreaId||!a.active||a.coverage_mode!=='administrative'||!serviceScopesOverlap(services,a.service_keys||[]))continue;const shared=(a.admin_area_codes||[]).filter(code=>areaAdminSelected.has(code));if(!shared.length)continue;const namesShared=shared.slice(0,3).map(code=>areaAdminSelected.get(code)||code).join(', ');const more=shared.length>3?` +${shared.length-3} more`:'';const otherPriority=Number(a.priority??100);conflicts.push(`${a.label}: ${namesShared}${more} · priority ${otherPriority}`)}if(!conflicts.length){el.textContent='No active smart-zone conflicts detected for the selected services.';el.classList.add('success');return}el.innerHTML=`<strong>${conflicts.length} overlapping zone${conflicts.length===1?'':'s'} detected.</strong> Your draft priority is ${priority}. Higher priority wins when the same service and postcode are covered by more than one zone.<br>${conflicts.map(x=>`• ${esc(x)}`).join('<br>')}`;el.classList.add('error')}
function renderAdminAreaCatalog(){const root=$('#areaAdminList'),selected=$('#areaAdminSelected'),count=$('#areaAdminSelectedCount');if(!root)return;const rows=visibleAdminAreas();if(count)count.textContent=`${areaAdminSelected.size} selected`;if(selected){selected.innerHTML=areaAdminSelected.size?[...areaAdminSelected].map(([code,name])=>`<button type="button" class="smart-area-chip" data-remove-admin-area="${esc(code)}">${esc(name)} <span>×</span></button>`).join(''):'<span class="admin-note">No councils or boroughs selected yet.</span>';$$('[data-remove-admin-area]').forEach(b=>b.onclick=()=>toggleAdminArea(b.dataset.removeAdminArea,false))}root.innerHTML=rows.length?rows.map(a=>`<label class="smart-area-option ${areaAdminSelected.has(a.code)?'selected':''}"><input type="checkbox" data-admin-area="${esc(a.code)}" ${areaAdminSelected.has(a.code)?'checked':''}><span><strong>${esc(a.name)}</strong><small>${esc(a.nation)} · ${esc(a.code)}</small></span></label>`).join(''):'<div class="crm-empty">No official areas match this search.</div>';$$('[data-admin-area]').forEach(x=>x.onchange=()=>toggleAdminArea(x.dataset.adminArea,x.checked));updateAreaDraftSummary();renderAreaConflicts()}
function browseFeatureCode(f){return String(f?.properties?.namdarCode||f?.properties?.LAD25CD||f?.properties?.LAD24CD||'')}
function browseFeatureName(f){return String(f?.properties?.namdarName||f?.properties?.LAD25NM||f?.properties?.LAD24NM||browseFeatureCode(f))}
function browseStyle(code){const selected=areaAdminSelected.has(code);return{weight:selected?4:2,fillOpacity:selected?.24:.05,dashArray:selected?'':'5 4',className:'admin-browse-boundary'}}
function refreshAdminBrowseStyles(){if(!areaAdminBrowseLayer)return;areaAdminBrowseLayer.eachLayer(layer=>{const code=browseFeatureCode(layer.feature);if(layer.setStyle)layer.setStyle(browseStyle(code))})}
function toggleAdminArea(code,on){const a=areaAdminCatalog.find(x=>x.code===code),name=a?.name||areaAdminSelected.get(code)||code;if(on)areaAdminSelected.set(code,name);else areaAdminSelected.delete(code);renderAdminAreaCatalog();refreshAdminBrowseStyles();scheduleAdminBoundaryLoad()}
async function loadAdminGeographyCatalog(){if(areaAdminCatalog.length){renderAdminAreaCatalog();return}setAreaAdminStatus('Loading official UK councils and boroughs…');try{const d=await api('/api/admin-geography?action=list');areaAdminCatalog=d.areas||[];renderAdminAreaCatalog();setAreaAdminStatus(`${areaAdminCatalog.length} official UK local authority areas loaded. Select from the list or click boundaries on the map.`,true);if($('#areaAdminFilter')?.value==='london')setTimeout(()=>loadVisibleAdminMap(true),120)}catch(e){setAreaAdminStatus(`Could not load official UK areas: ${e.message}`);$('#areaAdminList').innerHTML='<div class="crm-empty">Official area list unavailable. You can still use a custom boundary or radius.</div>'}}
function selectedAdminCodes(){return [...areaAdminSelected.keys()]}
function scheduleAdminBoundaryLoad(){clearTimeout(areaAdminLoadTimer);areaAdminLoadTimer=setTimeout(()=>loadSelectedAdminBoundaries(true),320)}
async function loadVisibleAdminMap(auto=false){if(!areaMap||!areaAdminCatalog.length)return;let rows=visibleAdminAreas();if(!rows.length){setAreaAdminStatus('No areas match the current filter/search.');return}if(rows.length>80){if(auto)return;setAreaAdminStatus(`There are ${rows.length} matching areas. Refine the search or filter to 80 or fewer before loading clickable map boundaries.`);return}const key=rows.map(x=>x.code).join(',');if(areaAdminBrowseLayer&&areaAdminBrowseKey===key){refreshAdminBrowseStyles();return}const btn=$('#areaBrowseMap');if(btn&&!auto)setBusy(btn,true,'Loading map…');setAreaAdminStatus(`Loading ${rows.length} clickable official boundar${rows.length===1?'y':'ies'}…`);try{const d=await api(`/api/admin-geography?action=boundaries&codes=${encodeURIComponent(key)}`);clearAreaAdminBrowseLayer();areaAdminBrowseKey=key;areaAdminBrowseLayer=L.geoJSON(d.geojson||{type:'FeatureCollection',features:[]},{style:f=>browseStyle(browseFeatureCode(f)),onEachFeature:(f,layer)=>{const code=browseFeatureCode(f),name=browseFeatureName(f);layer.bindTooltip(`${name} · click to ${areaAdminSelected.has(code)?'remove':'select'}`,{sticky:true});layer.on('click',e=>{if(e?.originalEvent)L.DomEvent.stopPropagation(e.originalEvent);toggleAdminArea(code,!areaAdminSelected.has(code));layer.setTooltipContent(`${name} · click to ${areaAdminSelected.has(code)?'remove':'select'}`)})}}).addTo(areaMap);const bounds=areaAdminBrowseLayer.getBounds();if(bounds.isValid())areaMap.fitBounds(bounds,{padding:[25,25],maxZoom:11});refreshAdminBrowseStyles();setAreaAdminStatus(`${rows.length} official areas are clickable on the map. Selected areas are highlighted.`,true)}catch(e){setAreaAdminStatus(`Could not load clickable boundaries: ${e.message}`)}finally{if(btn&&!auto)setBusy(btn,false)}}
async function loadSelectedAdminBoundaries(move=false){clearAreaAdminLayer();if(!areaAdminSelected.size){areaAdminGeojson=null;renderAreaDraftPreview(false);setAreaAdminStatus(areaAdminCatalog.length?`${areaAdminCatalog.length} official UK areas loaded. Select from the list or map.`:'');return}setAreaAdminStatus(`Loading ${areaAdminSelected.size} selected official boundar${areaAdminSelected.size===1?'y':'ies'}…`);try{const codes=selectedAdminCodes(),d=await api(`/api/admin-geography?action=boundaries&codes=${encodeURIComponent(codes.join(','))}`);areaAdminGeojson=d.geojson||null;if(!areaAdminGeojson)throw new Error('Boundary preview was empty.');if(areaMap&&window.L){const temp=L.geoJSON(areaAdminGeojson),bounds=temp.getBounds();if(bounds.isValid()){const c=bounds.getCenter();$('#areaLat').value=c.lat.toFixed(6);$('#areaLng').value=c.lng.toFixed(6);if(move&&!areaAdminBrowseLayer)areaMap.fitBounds(bounds,{padding:[30,30],maxZoom:11})}}renderAreaDraftPreview(false);setAreaAdminStatus(`${areaAdminSelected.size} selected area${areaAdminSelected.size===1?'':'s'} ready. Eligibility uses official authority codes.`,true)}catch(e){areaAdminGeojson=null;renderAreaDraftPreview(false);setAreaAdminStatus(`Selected names are kept, but the boundary preview could not load: ${e.message}`)}}
function updateAreaDraftSummary(){const el=$('#areaDraftSummary');if(!el)return;const mode=$('#areaCoverageMode')?.value||'administrative',inc=parseAreaRules($('#areaIncludePostcodes')?.value),exc=parseAreaRules($('#areaExcludePostcodes')?.value),services=selectedAreaServices(),priority=areaNum('#areaPriority')??100,serviceText=areaServicesLabel(services);if(mode==='administrative'){el.innerHTML=areaAdminSelected.size?`<strong>Smart coverage:</strong> ${areaAdminSelected.size} official council/borough area${areaAdminSelected.size===1?'':'s'} · <strong>${esc(serviceText)}</strong> · priority <strong>${priority}</strong>${inc.length?` · ${inc.length} include exception${inc.length===1?'':'s'}`:''}${exc.length?` · ${exc.length} exclude exception${exc.length===1?'':'s'}`:''}${$('#areaActive')?.checked?' · Active':' · Inactive'}`:'Choose one or more official UK councils or boroughs above.';return}const p=areaDraftPoint();if(p.latitude===null||p.longitude===null){el.textContent='Choose a centre point to preview this area.';return}const radius=p.radius&&p.radius>0?p.radius:null;el.innerHTML=`<strong>Draft:</strong> ${mode==='polygon'?'Precise boundary':'Circle radius'} · <strong>${esc(serviceText)}</strong> · priority <strong>${priority}</strong> · centre ${p.latitude.toFixed(6)}, ${p.longitude.toFixed(6)}${mode==='radius'&&radius?` · <strong>${radius} km</strong>`:mode==='polygon'?` · <strong>${areaBoundaryPoints.length} boundary points</strong>`:''}${inc.length?` · ${inc.length} include rule${inc.length===1?'':'s'}`:''}${exc.length?` · ${exc.length} exclude rule${exc.length===1?'':'s'}`:''}${$('#areaActive')?.checked?' · Active':' · Inactive'}`}
