async function addArea(){const btn=$('#addArea');setAreaEditorStatus('');let body;try{body=serviceAreaBody()}catch(e){setAreaEditorStatus(e.message);return}setBusy(btn,true,editingAreaId?'Saving…':'Adding…');try{let result;if(editingAreaId)result=await sb.from('service_areas').update({...body,updated_at:new Date().toISOString()}).eq('id',editingAreaId).select('*').single();else result=await sb.from('service_areas').insert(body).select('*').single();if(result.error)throw result.error;lastSavedAreaId=result.data?.id||editingAreaId;const wasEdit=!!editingAreaId,savedLabel=result.data?.label||body.label;resetAreaEditor();setAreaEditorStatus(wasEdit?`${savedLabel} coverage updated successfully ✓`:`${savedLabel} coverage added successfully ✓`,true);await areasTools();setTimeout(()=>{lastSavedAreaId=null;document.querySelector('.area-card.saved')?.classList.remove('saved')},2400)}catch(e){const msg=String(e?.message||e);if(msg.toLowerCase().includes('duplicate')||msg.toLowerCase().includes('unique'))setAreaEditorStatus('An area with this name already exists. Edit the existing one instead.');else setAreaEditorStatus(msg)}finally{setBusy(btn,false)}}

function parseAddressCsv(text){
  const rows=[];let row=[],cell='',quoted=false;
  for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'){if(quoted&&n==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&n==='\n')i++;row.push(cell);cell='';if(row.some(x=>String(x).trim()!==''))rows.push(row);row=[]}else cell+=c}
  row.push(cell);if(row.some(x=>String(x).trim()!==''))rows.push(row);
  if(rows.length<2)return[];const headers=rows[0].map(h=>String(h).trim().toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,''));
  return rows.slice(1).map(r=>Object.fromEntries(headers.map((h,i)=>[h,String(r[i]??'').trim()]))).filter(x=>Object.values(x).some(Boolean));
}
