async function importAddressCsv(){const file=$('#addressCsv')?.files?.[0],status=$('#addressImportStatus');if(!file){status.textContent='Choose a CSV file first.';return}setBusy($('#importAddresses'),true,'Importing…');try{const rows=parseAddressCsv(await file.text());if(!rows.length)throw new Error('The CSV has no data rows.');let imported=0,skipped=0;for(let i=0;i<rows.length;i+=500){const d=await api('/api/admin-address-directory',{method:'POST',body:JSON.stringify({action:'import',rows:rows.slice(i,i+500)})});imported+=Number(d.imported||0);skipped+=Number(d.skipped||0)}status.textContent=`Imported ${imported} approved addresses${skipped?` · skipped ${skipped} invalid rows`:''}.`;await addressDirectoryTools()}catch(e){status.textContent=e.message}finally{setBusy($('#importAddresses'),false)}}
