async function followupTools(){
  if(!allowed('analytics'))return;
  const type=$('#followupType')?.value||'all',status=$('#followupStatus')?.value||'all';
  try{
    const d=await api(`/api/admin-followups?type=${encodeURIComponent(type)}&status=${encodeURIComponent(status)}`),rows=d.rows||[],st=d.stats||{},rules=d.rules||{};
    if($('#followupPending'))$('#followupPending').textContent=st.pending||0;if($('#followupDueNow'))$('#followupDueNow').textContent=st.dueNow||0;if($('#followupSent'))$('#followupSent').textContent=st.sent||0;if($('#followupFailed'))$('#followupFailed').textContent=st.failed||0;
    if($('#followupRules'))$('#followupRules').innerHTML=`<strong>Automation rules</strong><br><small>Quotes: ${esc(rules.quoteReminders||'—')}<br>Invoices: ${esc(rules.invoiceReminders||'—')}<br>Unassigned staff: ${esc(rules.unassignedStaff||'—')}<br>Job attention: ${esc(rules.bookingAttention||'—')}<br>Cancelled bookings: ${esc(rules.cancelFollowUp||'—')}</small>`;
    $('#followupTable').innerHTML=rows.length?`<div class="table-scroll"><table class="admin-table crm-table"><thead><tr><th>Type</th><th>Recipient</th><th>Due / sent</th><th>Status</th><th>Attempts</th><th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(niceStatus(r.notification_type))}</strong><br><small>${esc(r.entity_type)} · ${esc(String(r.entity_id||'').slice(0,8))}</small></td><td>${esc(r.recipient_email||'—')}</td><td>${r.sent_at?`Sent ${dt(r.sent_at)}`:`Due ${dt(r.due_at)}`}</td><td><span class="crm-chip ${r.status==='sent'?'success':r.status==='failed'?'warning':''}">${esc(niceStatus(r.status))}</span>${r.error?`<br><small>${esc(r.error)}</small>`:''}</td><td>${Number(r.attempts||0)}</td><td><div class="crm-action-stack">${r.status!=='sent'?`<button class="ghost-btn small" data-followup-retry="${r.id}">Retry</button>`:''}${['pending','failed'].includes(r.status)?`<button class="ghost-btn small" data-followup-cancel="${r.id}">Cancel</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:crmEmpty('No follow-ups match these filters.');
    $$('[data-followup-retry]').forEach(b=>b.onclick=async()=>{setBusy(b,true,'Retrying…');try{await api('/api/admin-followups',{method:'POST',body:JSON.stringify({action:'retry',id:b.dataset.followupRetry})});await followupTools()}catch(e){$('#followupMessage').textContent=e.message}finally{setBusy(b,false)}});
    $$('[data-followup-cancel]').forEach(b=>b.onclick=async()=>{if(!confirm('Cancel this follow-up?'))return;setBusy(b,true,'Cancelling…');try{await api('/api/admin-followups',{method:'POST',body:JSON.stringify({action:'cancel',id:b.dataset.followupCancel})});await followupTools()}catch(e){$('#followupMessage').textContent=e.message}finally{setBusy(b,false)}});
    if($('#followupRunNow'))$('#followupRunNow').onclick=async()=>{const b=$('#followupRunNow');setBusy(b,true,'Checking…');$('#followupMessage').textContent='';try{const r=await api('/api/admin-followups',{method:'POST',body:JSON.stringify({action:'run'})});const x=r.result||{};$('#followupMessage').textContent=`Check complete · ${x.scan?.queued||0} newly queued · ${x.delivery?.sent||0} sent · ${x.delivery?.failed||0} failed.`;await followupTools()}catch(e){$('#followupMessage').textContent=e.message}finally{setBusy(b,false)}};
    if($('#followupRefresh'))$('#followupRefresh').onclick=followupTools;if($('#followupType'))$('#followupType').onchange=followupTools;if($('#followupStatus'))$('#followupStatus').onchange=followupTools;
  }catch(e){$('#followupTable').innerHTML=`<p>${esc(e.message)}</p>`}
}


function auditJson(value){try{return esc(JSON.stringify(value??null,null,2))}catch{return esc(String(value??''))}}
function auditActionLabel(v=''){return String(v||'').replaceAll('.',' › ').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())}
async function auditTools(){
  if(currentProfile?.role!=='admin')return;
  const q=($('#auditSearch')?.value||'').trim(),action=$('#auditAction')?.value||'all',entity=$('#auditEntity')?.value||'all',actor=$('#auditActor')?.value||'all';
  try{
    const d=await api(`/api/admin-audit?q=${encodeURIComponent(q)}&action=${encodeURIComponent(action)}&entity=${encodeURIComponent(entity)}&actor=${encodeURIComponent(actor)}`),rows=d.rows||[],st=d.stats||{};
    if($('#auditToday'))$('#auditToday').textContent=st.today||0;if($('#auditWeek'))$('#auditWeek').textContent=st.last7Days||0;if($('#auditActors'))$('#auditActors').textContent=st.staffActors||0;if($('#auditSystem'))$('#auditSystem').textContent=st.system||0;
    const setOptions=(el,items,current,labelFn=x=>auditActionLabel(x))=>{if(!el)return;el.innerHTML=`<option value="all">All ${el.id==='auditActor'?'staff':el.id==='auditEntity'?'areas':'actions'}</option>`+items.map(x=>{const value=typeof x==='string'?x:x.id,label=typeof x==='string'?labelFn(x):`${x.name}${x.email?` · ${x.email}`:''}`;return `<option value="${esc(value)}" ${value===current?'selected':''}>${esc(label)}</option>`}).join('')};
    setOptions($('#auditAction'),d.actions||[],action);setOptions($('#auditEntity'),d.entities||[],entity,x=>niceStatus(x));setOptions($('#auditActor'),d.actors||[],actor);
    $('#auditNote').textContent=d.retentionNote||'';
    $('#auditTable').innerHTML=rows.length?`<div class="table-scroll"><table class="admin-table crm-table audit-table"><thead><tr><th>When</th><th>Actor</th><th>Action</th><th>Affected record</th><th>Changes</th></tr></thead><tbody>${rows.map(r=>{const changed=r.changed_fields||[],before=r.before_data,after=r.after_data;return `<tr><td>${dt(r.created_at)}${r.request_id?`<br><small>${esc(r.request_id)}</small>`:''}</td><td><strong>${esc(r.actor_name||r.actor_email||'System')}</strong><br><small>${esc(r.actor_role||'system')}${r.actor_email&&r.actor_name?` · ${esc(r.actor_email)}`:''}</small></td><td><span class="crm-chip">${esc(auditActionLabel(r.action))}</span><br><small>${esc(r.summary||'')}</small></td><td><strong>${esc(niceStatus(r.entity_type))}</strong>${r.entity_id?`<br><code>${esc(String(r.entity_id).slice(0,48))}</code>`:''}</td><td>${changed.length?`<div class="audit-change-list">${changed.slice(0,10).map(x=>`<span>${esc(niceStatus(x))}</span>`).join('')}</div>`:'<small>No field diff recorded</small>'}${before!==null||after!==null?`<details class="audit-details"><summary>View before / after</summary><div class="audit-json-grid"><div><strong>Before</strong><pre>${auditJson(before)}</pre></div><div><strong>After</strong><pre>${auditJson(after)}</pre></div></div></details>`:''}</td></tr>`}).join('')}</tbody></table></div>`:crmEmpty('No activity matches these filters.');
    if($('#auditRefresh'))$('#auditRefresh').onclick=auditTools;if($('#auditAction'))$('#auditAction').onchange=auditTools;if($('#auditEntity'))$('#auditEntity').onchange=auditTools;if($('#auditActor'))$('#auditActor').onchange=auditTools;
  }catch(e){$('#auditTable').innerHTML=`<p>${esc(e.message)}</p>`}
}

function managementNotificationCategory(n={}){const hay=`${n.notification_type||''} ${n.permission_key||''} ${n.entity_type||''}`.toLowerCase();if(hay.includes('quote'))return'quotes';if(hay.includes('booking')||hay.includes('job'))return'bookings';if(hay.includes('payment')||hay.includes('invoice')||hay.includes('billing')||hay.includes('accounts'))return'billing';if(hay.includes('ticket')||hay.includes('support')||hay.includes('inbox')||hay.includes('email'))return'support';return'general'}
function managementNotificationIcon(n={}){const c=managementNotificationCategory(n);return c==='quotes'?'£':c==='bookings'?'▣':c==='billing'?'£':c==='support'?'✉':'•'}
function updateManagementNotificationBadge(count=0){const badge=$('#staffNotificationBadge');if(!badge)return;badge.textContent=count>99?'99+':String(count);badge.classList.toggle('hidden',count<1)}
function renderManagementNotificationPopover(){const root=$('#staffNotificationPopover');if(!root)return;const rows=staffNotificationInboxCache.slice(0,6);root.innerHTML=`<div class="notification-popover-head"><div><strong>Team notifications</strong><small>${staffNotificationInboxCache.filter(x=>!x.read_at).length} unread</small></div><button type="button" class="text-action" data-open-management-notifications>View all</button></div>${rows.length?rows.map(n=>`<button type="button" class="notification-popover-item ${n.read_at?'':'unread'}" data-open-staff-notification="${esc(n.id)}"><span class="management-notification-icon">${managementNotificationIcon(n)}</span><span><strong>${esc(n.title)}</strong><small>${esc(n.body||'')} · ${dt(n.created_at)}</small></span></button>`).join(''):`<div class="crm-empty compact">No new management notifications.</div>`}`;root.querySelector('[data-open-management-notifications]')?.addEventListener('click',()=>{root.classList.add('hidden');$('#staffNotificationBell')?.setAttribute('aria-expanded','false');document.querySelector('[data-tab="notifications"]')?.click()});root.querySelectorAll('[data-open-staff-notification]').forEach(b=>b.onclick=()=>openManagementNotification(b.dataset.openStaffNotification))}
async function loadStaffNotifications(renderPage=false){if(!currentSession)return;try{const inbox=await api('/api/staff-notifications?view=inbox');staffNotificationInboxCache=inbox.notifications||[];updateManagementNotificationBadge(inbox.unreadCount||0);renderManagementNotificationPopover();if(staffNotificationView==='inbox'){staffNotificationCache=staffNotificationInboxCache}else if(renderPage){const archived=await api('/api/staff-notifications?view=archived');staffNotificationCache=archived.notifications||[]}if(renderPage||!$('#notifications')?.classList.contains('hidden'))renderStaffNotificationList()}catch(e){if(renderPage&&$('#staffNotificationList'))$('#staffNotificationList').innerHTML=`<p>${esc(e.message)}</p>`}}
function filteredStaffNotifications(){const term=($('#staffNotifySearch')?.value||'').trim().toLowerCase();return (staffNotificationCache||[]).filter(n=>{const cat=managementNotificationCategory(n),hay=`${n.title||''} ${n.body||''} ${n.notification_type||''}`.toLowerCase(),f=staffNotificationFilter;return(!term||hay.includes(term))&&(f==='all'||(f==='unread'&&!n.read_at)||(f==='urgent'&&['urgent','high'].includes(n.priority))||f===cat)})}
function renderStaffNotificationList(){const root=$('#staffNotificationList');if(!root)return;const rows=filteredStaffNotifications();if(!rows.length){root.innerHTML=crmEmpty(staffNotificationView==='archived'?'No archived notifications match these filters.':'No notifications match these filters.');return}root.innerHTML=rows.map(n=>`<article class="management-notification-card ${n.read_at?'':'unread'} priority-${esc(n.priority||'normal')}"><button type="button" class="management-notification-main" data-open-staff-notification="${esc(n.id)}"><span class="management-notification-icon">${managementNotificationIcon(n)}</span><span class="management-notification-copy"><span class="management-notification-meta"><span class="crm-chip">${esc(niceStatus(managementNotificationCategory(n)))}</span>${['high','urgent'].includes(n.priority)?`<span class="crm-chip warning">${esc(niceStatus(n.priority))}</span>`:''}<small>${dt(n.created_at)}</small></span><strong>${esc(n.title)}</strong>${n.body?`<span>${esc(n.body)}</span>`:''}</span>${!n.read_at?'<i class="management-unread-dot" aria-label="Unread"></i>':''}</button><div class="management-notification-actions">${n.read_at?`<button class="text-action" type="button" data-staff-notify-action="unread" data-notification-id="${esc(n.id)}">Mark unread</button>`:`<button class="text-action" type="button" data-staff-notify-action="read" data-notification-id="${esc(n.id)}">Mark read</button>`}<button class="text-action" type="button" data-staff-notify-action="${staffNotificationView==='archived'?'restore':'archive'}" data-notification-id="${esc(n.id)}">${staffNotificationView==='archived'?'Restore':'Archive'}</button></div></article>`).join('');root.querySelectorAll('[data-open-staff-notification]').forEach(b=>b.onclick=()=>openManagementNotification(b.dataset.openStaffNotification));root.querySelectorAll('[data-staff-notify-action]').forEach(b=>b.onclick=()=>staffNotifyAction(b.dataset.notificationId,b.dataset.staffNotifyAction))}
async function staffNotifyAction(id,action,refresh=true){try{await api('/api/staff-notifications',{method:'PATCH',body:JSON.stringify({notificationId:id,action})});if(refresh)await loadStaffNotifications(true)}catch(e){alert(e.message)}}
async function openManagementNotification(id){const n=[...staffNotificationCache,...staffNotificationInboxCache].find(x=>x.id===id);if(!n)return;$('#staffNotificationPopover')?.classList.add('hidden');$('#staffNotificationBell')?.setAttribute('aria-expanded','false');if(!n.read_at)await staffNotifyAction(id,'read',false);const path=String(n.target_path||'');if(path.startsWith('/admin')){const u=new URL(path,location.origin),tab=u.searchParams.get('tab')||'overview',b=$$('[data-tab]').find(x=>x.dataset.tab===tab&&!x.classList.contains('hidden'));if(b){history.replaceState(null,'',u.pathname+u.search);await b.onclick?.();if(tab==='inbox'&&u.searchParams.get('thread'))await openSupportInboxThread(u.searchParams.get('thread'));else setTimeout(()=>focusManagementEntity(u.searchParams),120)}}else if(path.startsWith('/'))location.href=path;await loadStaffNotifications(false)}
function focusManagementEntity(params){const pairs=[['quote','data-quote-row'],['booking','data-booking-row']];for(const [key,attr] of pairs){const id=params.get(key);if(!id)continue;const row=document.querySelector(`[${attr}="${window.CSS?.escape?CSS.escape(id):id}"]`);if(row){row.scrollIntoView({behavior:'smooth',block:'center'});row.classList.add('management-target-flash');setTimeout(()=>row.classList.remove('management-target-flash'),2200)}break}}
function mailboxLabel(v='support'){return `${v==='accounts'||v==='billing'?'accounts':v}@namdar.co.uk`}
const SUPPORT_INBOX_VIEW_KEY='namdar_admin_inbox_view_v2';
function saveSupportInboxView(){try{sessionStorage.setItem(SUPPORT_INBOX_VIEW_KEY,JSON.stringify({status:$('#supportInboxStatus')?.value||'open',mailbox:$('#supportInboxMailbox')?.value||'all'}))}catch{}}
function restoreSupportInboxView(){try{const v=JSON.parse(sessionStorage.getItem(SUPPORT_INBOX_VIEW_KEY)||'null');if(v&&['open','awaiting_staff','awaiting_customer','closed','all'].includes(v.status)&&$('#supportInboxStatus'))$('#supportInboxStatus').value=v.status;if(v&&['all','support','bookings','accounts','hello'].includes(v.mailbox)&&$('#supportInboxMailbox'))$('#supportInboxMailbox').value=v.mailbox}catch{}}
function supportInboxFilterState(){return{term:($('#supportInboxSearch')?.value||'').trim().toLowerCase(),status:$('#supportInboxStatus')?.value||'open',mailbox:$('#supportInboxMailbox')?.value||'all'}}
function supportInboxVisibleThreads(){const{term,status,mailbox}=supportInboxFilterState(),rows=(supportInboxCache||[]).filter(t=>{const hay=`${t.customer_name||''} ${t.customer_email||''} ${t.subject||''} ${t.last_message_preview||''}`.toLowerCase(),statusOk=status==='all'||(status==='open'&&t.status!=='closed')||t.status===status,mailOk=mailbox==='all'||t.mailbox===mailbox||(['accounts','billing'].includes(mailbox)&&['accounts','billing'].includes(t.mailbox));return(!term||hay.includes(term))&&statusOk&&mailOk});if(status==='closed')rows.sort((a,b)=>new Date(b.updated_at||b.last_message_at)-new Date(a.updated_at||a.last_message_at));return rows}
function supportInboxAssigneeLabel(t={}){if(!t.assigned_to)return'Unassigned';if(t.assigned_to===currentSession?.user?.id)return'Assigned to you';const p=(supportInboxStaff||[]).find(x=>x.id===t.assigned_to);return p?`Assigned · ${p.full_name||p.email}`:'Assigned'}
function supportInboxStatusLabel(v=''){return v==='awaiting_staff'?'Needs reply':v==='awaiting_customer'?'Waiting for customer':niceStatus(v)}
function updateSupportInboxSummary(){const rows=supportInboxVisibleThreads(),all=supportInboxCache||[],needs=all.filter(x=>x.status==='awaiting_staff').length,waiting=all.filter(x=>x.status==='awaiting_customer').length,open=all.filter(x=>x.status!=='closed').length,closed=all.filter(x=>x.status==='closed').length,unread=all.reduce((a,t)=>a+Number(t.unread_count||0),0),status=$('#supportInboxStatus')?.value||'open';if($('#supportInboxSummary'))$('#supportInboxSummary').textContent=`${rows.length} shown · ${unread} unread`;if($('#supportInboxNeedsReply'))$('#supportInboxNeedsReply').textContent=needs;if($('#supportInboxWaiting'))$('#supportInboxWaiting').textContent=waiting;if($('#supportInboxOpenCount'))$('#supportInboxOpenCount').textContent=open;if($('#supportInboxClosedCount'))$('#supportInboxClosedCount').textContent=closed;if($('#supportInboxAllCount'))$('#supportInboxAllCount').textContent=all.length;if($('#supportInboxUnread'))$('#supportInboxUnread').textContent=unread;$$('[data-inbox-quick]').forEach(b=>b.classList.toggle('active',b.dataset.inboxQuick===status));const f=supportInboxFilterState(),custom=!!f.term||f.status!=='open'||f.mailbox!=='all';$('#supportInboxClearFilters')?.classList.toggle('hidden',!custom)}
function updateSupportInboxUpdated(message=''){const el=$('#supportInboxUpdated');if(!el)return;if(message){el.textContent=message;return}el.textContent=supportInboxLastUpdated?`Updated ${supportInboxLastUpdated.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}`:'Not refreshed yet'}
function resetSupportInboxFilters(){if($('#supportInboxSearch'))$('#supportInboxSearch').value='';if($('#supportInboxStatus'))$('#supportInboxStatus').value='open';if($('#supportInboxMailbox'))$('#supportInboxMailbox').value='all';saveSupportInboxView();renderSupportInboxList()}
function renderSupportInboxList(){const root=$('#supportInboxList');if(!root)return;const rows=supportInboxVisibleThreads();updateSupportInboxSummary();if(!rows.length){const hasAny=(supportInboxCache||[]).length>0,filtered=hasAny&&($('#supportInboxSearch')?.value||$('#supportInboxStatus')?.value!=='open'||$('#supportInboxMailbox')?.value!=='all');root.innerHTML=`<div class="crm-empty support-inbox-empty"><strong>${hasAny?'No conversations match':'Inbox clear'}</strong><span>${hasAny?($('#supportInboxStatus')?.value==='closed'?'Closed conversations are kept here permanently until you reopen them.':'Try changing or clearing the current filters.'):'New customer emails will appear here automatically.'}</span>${filtered?'<button type="button" class="ghost-btn small" data-inbox-reset>Clear filters</button>':''}</div>`;root.querySelector('[data-inbox-reset]')?.addEventListener('click',resetSupportInboxFilters);return}root.innerHTML=rows.map(t=>{const preview=String(t.last_message_preview||'').trim(),direction=t.last_direction==='outbound'?'You: ':'';return `<button type="button" class="support-inbox-row ${Number(t.unread_count||0)>0?'unread':''} ${supportInboxOpenId===t.id?'active':''}" data-inbox-thread="${esc(t.id)}"><span class="support-inbox-row-top"><strong>${esc(t.customer_name||t.customer_email)}</strong><small>${dt(t.last_message_at)}</small></span><span class="support-inbox-subject">${esc(t.subject)}</span>${preview?`<span class="support-inbox-preview">${esc(direction+preview)}</span>`:''}<span class="support-inbox-row-meta"><span class="inbox-mailbox-tag">${esc(mailboxLabel(t.mailbox))}</span><span class="inbox-status-tag ${esc(t.status)}">${esc(supportInboxStatusLabel(t.status))}</span>${t.priority!=='normal'?`<span class="priority-text ${esc(t.priority)}">${esc(niceStatus(t.priority))}</span>`:''}<span class="support-inbox-assignee">${esc(supportInboxAssigneeLabel(t))}</span>${t.unread_count?`<b aria-label="${Number(t.unread_count)} unread messages">${Number(t.unread_count)}</b>`:''}</span></button>`}).join('');root.querySelectorAll('[data-inbox-thread]').forEach(b=>b.onclick=()=>openSupportInboxThread(b.dataset.inboxThread))}
async function supportInboxTools(options={}){if(!(allowed('inbox')||allowed('tickets')||allowed('bookings')||allowed('payments')))return;if(supportInboxRefreshing)return;supportInboxRefreshing=true;const root=$('#supportInboxList'),btn=$('#supportInboxRefresh'),manual=options.manual===true;if(manual&&btn)setBusy(btn,true,'Refreshing…');if(manual)updateSupportInboxUpdated('Refreshing inbox…');try{const d=await api('/api/support-inbox');supportInboxCache=d.threads||[];supportInboxStaff=d.staff||[];supportInboxLastUpdated=new Date();renderSupportInboxList();updateSupportInboxUpdated();const wanted=new URLSearchParams(location.search).get('thread');if(options.refreshOpen&&supportInboxOpenId&&supportInboxCache.some(t=>t.id===supportInboxOpenId))await openSupportInboxThread(supportInboxOpenId,{preserveDraft:true});else if(wanted&&wanted!==supportInboxOpenId)await openSupportInboxThread(wanted)}catch(e){updateSupportInboxUpdated(`Refresh failed · ${e.message}`);if(root&&!options.silent)root.innerHTML=`<div class="crm-empty"><strong>Could not refresh inbox</strong><span>${esc(e.message)}</span></div>`}finally{supportInboxRefreshing=false;if(manual&&btn)setBusy(btn,false)}}
function attachmentLabel(a={}){return a.filename||a.name||a.file_name||a.content_disposition||'Attachment'}
function saveSupportInboxDraft(id=supportInboxOpenId){const box=$('#supportInboxReply');if(id&&box)supportInboxDrafts.set(id,box.value)}
